INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 30, 'theory', 'Quiz: migrations and backups');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 0, 'What do you do if a bug is found in an already applied migration?', '["Edit the migration file", "Delete its record from the service table", "Reinstall the database", "Write a new migration that fixes the bug and leave the old one alone"]', 3, 'An applied migration is immutable, otherwise different environments end up with different schemas.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 1, 'How do you rename a column in a running system without downtime?', '["With a single ALTER … RENAME command at any time", "Add a new column, write to both, move the history in batches, switch the reads, and drop the old one in a separate migration", "Stop all servers for the night", "Copy the whole table"]', 1, 'Each step is compatible with both the previous and the next version of the code, so the rollout can be stopped at any point.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 2, 'Why is a single UPDATE over a hundred million rows dangerous?', '["It holds locks, bloats the log, and rolls back entirely on failure; it is better to update in batches with a pause", "It is unavailable in most databases", "It does not change the data", "It is always faster than batches"]', 0, 'Batches make the operation resumable and give replication time to catch up.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 3, 'How does a replica differ from a backup?', '["It does not, they are the same thing", "A replica protects against logical errors, a backup protects against hardware failure", "A replica also repeats erroneous commands, such as dropping a table, while a backup lets you go back to the moment before the error", "A backup is always more up to date than a replica"]', 2, 'You need both levels; backups are stored separately from the main system.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 30, 4, 'What does "point-in-time recovery" mean?', '["Restoring a backup without the log", "Copying a dump to a new server", "Stopping the database for a fixed time", "Restoring a physical backup and replaying the write-ahead log archive up to the desired moment"]', 3, 'This lets you go back to a second before an accidental delete; the log archiving frequency determines the acceptable data loss.');
